import { createMemo, type JSX, type ParentComponent } from "solid-js";

// Used for intellisense & JSDoc
// eslint-disable-next-line @typescript-eslint/no-unused-vars
import type { L10n } from "#core/ui-next/components/l10n.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

const TEXT_SIZES = ["text-2xs", "text-xs", "text-sm", "text-base", "text-lg", "text-xl", "text-2xl", "text-custom"];

const HeaderComponent: ParentComponent<JSX.HTMLAttributes<HTMLDivElement>> = (props) => {
	const baseClasses = "uppercase tracking-100 fxs-header pointer-events-auto font-title";
	const textSize = createMemo(() => (TEXT_SIZES.some((size) => props.class?.includes(size)) ? "" : "text-lg"));

	return (
		<div
			{...props}
			class={`${baseClasses} ${textSize()} ${props.class ?? ""}`}
			data-name="Header"
		>
			{props.children}
		</div>
	);
};

/**
 * A Header Text Component.
 * Used to display text headers with a gradient.
 * Meant to be used in conjunction with {@link L10n}.
 * ```tsx
 * <Header><L10n.Compose text="LOC_HEADER_TEXT" /></Header>
 * ```
 * Default implementation: {@link ButtonComponent} Based on: {@link Activatable}
 * Default implementation: {@link HeaderComponent}
 */
export const Header = ComponentRegistry.register("Header", HeaderComponent);
